    padding: 100px 0;
    color: var(--pure-white);
}

.final-cta h2 {
    color: var(--pure-white);
    margin-bottom: 20px;
}

.final-cta p {
    color: rgba(255, 255, 255, 0.8);
    margin-bottom: 40px;
    font-size: 20px;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.text-center {
    text-align: center;
}

.cta-elevated {
    box-shadow: 0 8px 16px rgba(0,0,0,0.2);
}

/* --- Footer --- */
.site-footer {
    background-color: var(--cool-black);
    padding: 60px 0 30px;
}

.footer-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    padding-bottom: 40px;
    margin-bottom: 30px;
}

.brand-text.white {
    color: var(--pure-white);
}

.footer-contact a {
    color: var(--light-gray);
    text-decoration: none;
    font-size: 16px;
    transition: color 0.2s;
}

.footer-contact a:hover {
    color: var(--deloitte-green);
}

.footer-bottom {
    text-align: center;
}

.footer-bottom p {
    font-size: 14px;
    color: var(--cool-gray);
}

/* --- Animation Classes --- */
.fade-up {
    opacity: 0;
    transform: translateY(30px);
    transition: opacity 0.8s ease-out, transform 0.8s ease-out;
}

.fade-up.visible {
    opacity: 1;
    transform: translateY(0);
}

/* --- Responsive Adjustments --- */
@media (max-width: 1024px) {
    .hero-container {
        grid-template-columns: 1fr;
        text-align: center;
    }
    .hero-subtitle {
        margin: 0 auto 40px;
    }
    .hero-cta {
        justify-content: center;
    }
    .cards-grid {
        grid-template-columns: 1fr;
    }
    .feature-row, .feature-row.reverse {
        flex-direction: column;
        gap: 40px;
    }
}

@media (max-width: 768px) {
    .navbar { padding: 0 24px; }
    .nav-links { display: none; }
    .metrics-container { flex-direction: column; gap: 40px; }
    .metric-divider { width: 60px; height: 1px; }
    .hero-title { font-size: 40px; }
}

