			if(el.getBoundingClientRect().top < window.innerHeight) {
				el.classList.add('visible');
			}
		});
	}, 150);
}

function initDashboard() {
	const rawData = (typeof appsmith !== 'undefined' && appsmith.model) ? appsmith.model.data : [];
	renderKPIs(rawData);
	renderCharts(rawData);
	renderInsights(rawData);
	renderTables(rawData);
	initAnimations();
}

if (typeof appsmith !== 'undefined') {
	appsmith.onReady(() => {
		initDashboard();
		appsmith.onModelChange((newModel) => {
			renderKPIs(newModel.data);
			renderCharts(newModel.data);
			renderInsights(newModel.data);
			renderTables(newModel.data);
		});
	});
} else {
	document.addEventListener("DOMContentLoaded", initDashboard);
}

function renderKPIs(dbData) {
	const isLive = dbData && dbData.length > 0;

	const total = isLive ? dbData.length : 152490;
	const highRisk = isLive ? dbData.filter(d => d[FIELD_MAP.riskLevel] === 'HIGH' || d[FIELD_MAP.riskLevel] === 'CRITICAL').length : 142;
	const duplicates = isLive ? dbData.filter(d => d[FIELD_MAP.issueType] && d[FIELD_MAP.issueType].toLowerCase().includes('duplicate')).length : 38;
	const compliance = isLive ? dbData.filter(d => d[FIELD_MAP.issueType] && d[FIELD_MAP.issueType].toLowerCase().includes('compliance')).length : 12;
	const vendors = isLive ? new Set(dbData.filter(d => d[FIELD_MAP.status] === 'Flagged').map(d => d[FIELD_MAP.vendorName])).size : 5;

	document.getElementById('kpi-total').innerText = total.toLocaleString();
	document.getElementById('kpi-risk').innerText = highRisk.toLocaleString();
	document.getElementById('kpi-dup').innerText = duplicates.toLocaleString();
	document.getElementById('kpi-comp').innerText = compliance.toLocaleString();
	document.getElementById('kpi-vendor').innerText = vendors.toLocaleString();
}

function renderCharts(dbData) {
	const isLive = dbData && dbData.length > 0;

	const highRiskData = isLive ? dbData.filter(d => d[FIELD_MAP.riskScore] > 70).map(d => ({x: d[FIELD_MAP.volume] || Math.random()*100, y: d[FIELD_MAP.riskScore], r: 8})) : [{x: 45, y: 80, r: 8}, {x: 120, y: 95, r: 12}, {x: 80, y: 75, r: 6}];
	const safeData = isLive ? dbData.filter(d => d[FIELD_MAP.riskScore] <= 70).map(d => ({x: d[FIELD_MAP.volume] || Math.random()*200, y: d[FIELD_MAP.riskScore], r: 6})) : [{x: 300, y: 20, r: 10}, {x: 450, y: 15, r: 6}, {x: 200, y: 35, r: 8}];
	const trendData = isLive ? [12, 19, 8, dbData.filter(d => d[FIELD_MAP.riskLevel] === 'HIGH').length] : [12, 19, 8, 22];

	const ctx1 = document.getElementById('matrixChart');
	const ctx2 = document.getElementById('trendChart');
	if(!ctx1 || !ctx2) return;

	if(matrixChart) matrixChart.destroy();
	matrixChart = new Chart(ctx1.getContext('2d'), {
		type: 'bubble',
		data: { datasets: [
			{ label: 'High Risk', data: highRiskData, backgroundColor: '#0F0B0B' }, 
			{ label: 'Safe', data: safeData, backgroundColor: '#86BC25' }
		] },
		options: { 
			maintainAspectRatio: false, 
			plugins: { legend: { display: false } },
			scales: {
				x: { grid: { color: '#E8E8E8' }, ticks: { color: '#75787B' } },
				y: { grid: { color: '#E8E8E8' }, ticks: { color: '#75787B' } }
			}
		}
	});

	if(trendChart) trendChart.destroy();
	trendChart = new Chart(ctx2.getContext('2d'), {
		type: 'line',
		data: { labels: ['Q1', 'Q2', 'Q3', 'Q4'], datasets: [{ data: trendData, borderColor: '#004F59', backgroundColor: 'rgba(0, 79, 89, 0.1)', fill: true, tension: 0.4 }] },
		options: { 
			maintainAspectRatio: false, 
			plugins: { legend: { display: false } },
			scales: {
				x: { grid: { color: '#E8E8E8' }, ticks: { color: '#75787B' } },
				y: { grid: { color: '#E8E8E8' }, ticks: { color: '#75787B' } }
			}
		}
	});
}

function renderInsights(dbData) {
	const isLive = dbData && dbData.length > 0;

	const riskHTML = isLive ? dbData.filter(d => d[FIELD_MAP.riskLevel] === 'HIGH').slice(0,3).map(d => `<li>${d[FIELD_MAP.vendorName]} <span>${d[FIELD_MAP.riskScore]}/100</span></li>`).join('') : `<li>Tata Spares <span>92/100</span></li><li>Reliance Log. <span>85/100</span></li><li>Global Corp <span>78/100</span></li>`;
	const gstinHTML = isLive ? dbData.filter(d => d[FIELD_MAP.issueType] === 'Missing GSTIN').slice(0,3).map(d => `<li>${d[FIELD_MAP.vendorName]} <span>${d[FIELD_MAP.id]}</span></li>`).join('') : `<li>Apex Traders <span>INV-812</span></li><li>SteelCo <span>INV-904</span></li>`;
	const policyHTML = isLive ? dbData.filter(d => d[FIELD_MAP.issueType] === 'Policy Violation').slice(0,3).map(d => `<li>${d[FIELD_MAP.vendorName]} <span>${d[FIELD_MAP.id]}</span></li>`).join('') : `<li>Limit Exceeded <span>3</span></li><li>Unapproved PO <span>1</span></li>`;
	const weekendCount = isLive ? dbData.filter(d => d[FIELD_MAP.issueType] === 'Weekend Entry').length : 47;

	const elRisk = document.getElementById('list-risk');
	const elGstin = document.getElementById('list-gstin');
	const elPolicy = document.getElementById('list-policy');
	const elWeekend = document.getElementById('stat-weekend');

	if(elRisk) elRisk.innerHTML = riskHTML;
	if(elGstin) elGstin.innerHTML = gstinHTML;
	if(elPolicy) elPolicy.innerHTML = policyHTML;
	if(elWeekend) elWeekend.innerText = weekendCount;
}

function renderTables(dbData) {
	const isLive = dbData && dbData.length > 0;

	const eqBody = document.querySelector('#table-eq tbody');
	const logsBody = document.querySelector('#table-logs tbody');
	if(!eqBody || !logsBody) return;

	if (isLive) {
		eqBody.innerHTML = dbData.filter(d => d[FIELD_MAP.status] === 'Escalated').slice(0,3).map(d => `<tr><td>${d[FIELD_MAP.id]}</td><td>${d[FIELD_MAP.vendorName]}</td><td>${d[FIELD_MAP.issueType]}</td><td><span style="font-weight: 600; color: #E24C4B;">Escalated</span></td></tr>`).join('');
		logsBody.innerHTML = dbData.slice(0,3).map(d => `<tr><td style="color:#75787B">${d[FIELD_MAP.timestamp] || '10:42'}</td><td><strong style="font-weight: 500;">${d[FIELD_MAP.agent] || 'Rule Engine'}</strong></td><td>Flagged ${d[FIELD_MAP.id]} for limit breach</td></tr>`).join('');
	} else {
		eqBody.innerHTML = `<tr><td><span style="font-family: monospace;">EQ-1042</span></td><td>Reliance Log.</td><td>Compliance</td><td><span style="font-weight: 600; color: #E24C4B;">Escalated</span></td></tr><tr><td><span style="font-family: monospace;">EQ-1043</span></td><td>Tata Spares</td><td>Duplicate</td><td><span style="font-weight: 600; color: #ff991f;">Pending</span></td></tr>`;
		logsBody.innerHTML = `<tr><td style="color:#75787B">10:42:01</td><td><strong style="font-weight: 600;">Rule Engine</strong></td><td>Flagged INV-892 for limit breach</td></tr><tr><td style="color:#75787B">10:41:15</td><td><strong style="font-weight: 600;">3-Way Match</strong></td><td>Cleared PO-209 against GRN</td></tr>`;
	}
}

