srcDoc.css:
:root {
  --deloitte-green: #86BC25;
  --cool-black: #0F0B0B;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --bg-canvas: #FBFBFB;
  --deloitte-blue: #00A3E0;
  --dark-teal: #004F59;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-canvas);
  color: var(--cool-black);
  overflow-x: hidden;
}

.genw-dashboard {
  display: flex;
  flex-direction: column;
  padding: 32px;
}

/* Page Header */
.page-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 24px;
  border-bottom: 1px solid var(--light-gray);
  padding-bottom: 16px;
}

.green-dot {
  width: 14px;
  height: 14px;
  background-color: var(--deloitte-green);
  border-radius: 50%;
}

.page-title {
  margin: 0;
  color: var(--cool-black);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.page-subtitle {
  margin: 0;
  font-size: 16px;
  color: var(--cool-gray);
  font-weight: 400;
  margin-left: 12px;
}

/* Generic block/card formatting */
.dashboard-card {
  background: #FFFFFF;
  border: 1px solid var(--light-gray);
  border-radius: 8px;
  padding: 20px 24px;
  box-shadow: 0 4px 12px rgba(15, 11, 11, 0.03);
  display: flex;
  flex-direction: column;
  text-align: left;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.dashboard-card:hover {
  box-shadow: 0 8px 24px rgba(15, 11, 11, 0.06);
}

/* Layout Grids */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.chart-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-bottom: 24px;
}

.insights-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 24px;
}

.tables-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-bottom: 24px;
}

/* KPI Element Styling */
.kpi-label {
  font-size: 14px;
  font-weight: 700;
  color: var(--cool-black);
  text-transform: uppercase;
  margin-bottom: 4px;
}

.kpi-desc {
  font-size: 13px;
  color: var(--cool-gray);
  font-weight: 400;
  margin-bottom: 16px;
}

.kpi-value {
  font-size: 32px;
  font-weight: 800;
  color: var(--cool-black);
  letter-spacing: 0.5px;
  margin-top: auto;
}

.kpi-value.alert-text {
  color: #E24C4B;
}

/* Common Element Styling */
.panel-header, .block-title, .table-header {
  font-size: 14px;
  font-weight: 700;
  color: var(--cool-black);
  letter-spacing: 0.5px;
  margin-bottom: 20px;
  border-bottom: 1px solid var(--light-gray);
  padding-bottom: 12px;
  text-transform: uppercase;
}

.canvas-wrapper {
  position: relative;
  height: 260px;
  width: 100%;
}

.highlight-bg {
  border-top: 6px solid var(--deloitte-green);
}

/* List Styling */
.mini-list {
  list-style: none;
  padding: 0;
  margin: 0;
  font-size: 14px;
  color: var(--cool-black);
  font-weight: 400;
}

.mini-list li {
  padding: 12px 0;
  border-bottom: 1px dashed var(--light-gray);
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: all 0.2s ease;
}

.mini-list li:hover {
  padding-left: 6px;
  color: var(--deloitte-green);
  cursor: pointer;
}

.mini-list li span {
  font-weight: 700;
  color: var(--dark-teal);
  background: rgba(0, 79, 89, 0.05);
  padding: 2px 8px;
  border-radius: 4px;
}

.giant-stat {
  font-size: 42px;
  font-weight: 800;
  color: var(--cool-black);
  margin-top: 8px;
  letter-spacing: 0.5px;
}

.stat-sub {
  font-size: 13px;
  color: var(--cool-gray);
  font-weight: 400;
}

/* Data Tables */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  font-weight: 400;
  text-align: left;
}

.data-table th {
  padding: 12px 8px;
  font-size: 12px;
  font-weight: 700;
  color: var(--cool-gray);
  border-bottom: 1px solid var(--light-gray);
  letter-spacing: 0.5px;
  text-transform: uppercase;
}

.data-table td {
  padding: 16px 8px;
  border-bottom: 1px solid var(--bg-canvas);
  color: var(--cool-black);
  transition: background-color 0.2s ease;
}

.data-table tbody tr:hover td {
  background-color: var(--bg-canvas);
  color: var(--deloitte-green);
  cursor: pointer;
}

/* --- Animation Classes --- */
.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive Overrides */
@media screen and (max-width: 1400px) {
  .insights-row {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media screen and (max-width: 768px) {
  .kpi-grid, .chart-grid, .insights-row, .tables-grid {
    grid-template-columns: 1fr;
  }
  .data-table {
    display: block;
    overflow-x: auto;
    white-space: nowrap;
  }
}

