setTimeout(() => {
    if (typeof lucide !== 'undefined') {
        lucide.createIcons();
    }
}, 100);

// --- 1. Mock Queue Data ---
let queueData = [
  { id: "INV-9921", score: 98, vendor: "TechCorp Logistics" },
  { id: "PO-4412", score: 85, vendor: "Global Supplies Inc." },
  { id: "INV-1102", score: 81, vendor: "Apex Solutions" },
  { id: "GRN-0922", score: 75, vendor: "Prime Manufacturing" },
];

let activeItemId = "INV-9921"; // Default selected item

function renderQueue(dataToRender = queueData) {
  const qList = document.getElementById('queue-list');
  if (!qList) return;
  qList.innerHTML = dataToRender.map((item) => {
    let isActive = item.id === activeItemId;
    let bgClass = isActive ? 'bg-[#F9FBE7] border-deloitte-green shadow-sm ring-1 ring-deloitte-green' : 'bg-white border-deloitte-lightGray hover:border-deloitte-coolGray hover:bg-gray-50';
    let scoreClass = item.score > 90 ? 'text-[#D32F2F] bg-[#FFEBEE]' : 'text-[#F9A825] bg-[#FFF8E1]';
    return `
      <div onclick="selectQueueItem('${item.id}', '${item.vendor}', ${item.score})" class="p-3 rounded-lg border cursor-pointer transition-all ${bgClass}">
         <div class="flex justify-between items-center mb-1">
           <span class="font-semibold text-sm text-deloitte-black">${item.id}</span>
           <span class="text-xs font-bold px-2 py-0.5 rounded ${scoreClass}">${item.score} Risk</span>
         </div>
         <p class="text-xs text-deloitte-coolGray">${item.vendor}</p>
      </div>
    `;
  }).join('');
}

// Interactivity for Queue Items
window.selectQueueItem = function(id, vendor, score) {
    activeItemId = id;

    // 1. Re-render queue to update the active UI styles
    renderQueue();

    // 2. Update AI Context dynamically
    assistantData.context.recordHtml = `<strong>Active Audit ID:</strong> ${id} | Vendor: ${vendor}`;
    console.log("Updated AI context to:", assistantData.context.recordHtml);

    // 3. Provide visual feedback
    // Update main panel UI (Simulated mock updates for immersion)
    const matchInvId = document.getElementById('match-inv-id');
    if (matchInvId) matchInvId.innerText = id;

    const reasoningText = document.getElementById('ai-reasoning-text');
    if (reasoningText) {
        reasoningText.innerHTML = `Analyzing ${id} from <em class="text-deloitte-black">${vendor}</em>. Risk score is ${score}. Detailed anomaly heuristics are currently being compiled by the Agent Builder framework...`;
    }

    // 4. Update Chat Visuals
    if (chatOpen) {
       const history = document.getElementById('chat-history');
       const badge = document.createElement('div');
       badge.className = 'mx-auto w-fit text-xs font-semibold bg-[#E1F5FE] text-deloitte-blue px-3 py-1 rounded-full border border-[#B3E5FC] mb-2';
       badge.innerHTML = `Switched Context to: ${id}`;
       history.appendChild(badge);
       history.scrollTop = history.scrollHeight;
    } else {
       const fab = document.getElementById('chat-fab');
       if(fab) {
           // Bounce the chat button to notify user context changed
           fab.classList.add('animate-bounce');
           setTimeout(() => fab.classList.remove('animate-bounce'), 2000);
       }
    }
}

// Action Bar Dummy Handler
window.handleActionClick = function(actionName) {
    alert(`Triggered action: ${actionName} for ${activeItemId}. In production, this fires an Appsmith webhook.`);
}

// Queue Search Functionality
setTimeout(() => {
    const searchInput = document.getElementById('queue-search');
    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            const filtered = queueData.filter(d => 
                d.id.toLowerCase().includes(term) || 
                d.vendor.toLowerCase().includes(term)
            );
            renderQueue(filtered);
        });
    }
}, 200);

// --- 2. Chatbot Logic ---
let chatOpen = false;

window.toggleChat = function() {
  chatOpen = !chatOpen;
  const chatWindow = document.getElementById('chat-window');
  if (chatOpen) {
    chatWindow.classList.remove('hidden');
    setTimeout(() => {
      chatWindow.classList.remove('translate-y-4', 'opacity-0');
      chatWindow.classList.add('translate-y-0', 'opacity-100');
    }, 10);
  } else {
    chatWindow.classList.remove('translate-y-0', 'opacity-100');
    chatWindow.classList.add('translate-y-4', 'opacity-0');
    setTimeout(() => {
      chatWindow.classList.add('hidden');
    }, 300);
  }
}

const assistantData = {
  initialMessage: "<strong>Hello, How can I assist You Today?</strong><br>",
  suggestions: [
    "Summarize financial impact", 
    "Draft escalation email to VEND1011"
  ],
  context: {
    recordHtml: `<strong>Active Audit ID:</strong> INV-9921 | Vendor: TechCorp Logistics`,
    evidenceLinks: []
  }
};

function initAssistant() {
  const history = document.getElementById('chat-history');
  const suggestionsBox = document.getElementById('chat-suggestions');
  if (!history || !suggestionsBox) return;

  history.innerHTML = '';
  suggestionsBox.innerHTML = '';

  appendMessage('bot', assistantData.initialMessage);
  assistantData.suggestions.forEach(s => {
    suggestionsBox.innerHTML += `<button class="px-3 py-1 bg-white border border-deloitte-green text-deloitte-green hover:bg-deloitte-green hover:text-white rounded-full text-xs font-semibold transition-colors" onclick="fillInput('${s}')">${s}</button>`;
  });

  // Render initial queue data
  renderQueue();
}

function appendMessage(sender, text) {
  const history = document.getElementById('chat-history');
  if (!history) return;
  const isUser = sender === 'user';
  const msgDiv = document.createElement('div');
  msgDiv.className = isUser 
    ? 'ml-auto max-w-[85%] bg-deloitte-green text-white p-3 rounded-lg rounded-tr-none shadow-sm' 
    : 'mr-auto max-w-[85%] bg-white border border-deloitte-lightGray text-deloitte-black p-3 rounded-lg rounded-tl-none shadow-sm';
  msgDiv.innerHTML = text;
  history.appendChild(msgDiv);
  history.scrollTop = history.scrollHeight;
}

window.fillInput = function(text) {
    const suggestionsBox = document.getElementById('chat-suggestions');
    const inputField = document.getElementById('chat-input');
    if (suggestionsBox) suggestionsBox.style.display = "none";
    if(inputField) {
        inputField.value = text;
        inputField.focus();
    }
}

function parseMarkdown(text) {
    if (!text) return "";
    return text
        .replace(/^### (.*$)/gim, '<h3 class="font-bold text-md mt-2">$1</h3>')
        .replace(/^## (.*$)/gim, '<h2 class="font-bold text-lg mt-2">$1</h2>')
        .replace(/^# (.*$)/gim, '<h1 class="font-bold text-xl mt-2">$1</h1>')
        .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>')
        .replace(/\*(.*)\*/gim, '<em>$1</em>')
        .replace(/`(.*?)`/gim, '<code class="bg-[#F3F4F6] px-1 py-0.5 rounded text-[#D32F2F] font-mono text-sm">$1</code>')
        .replace(/\n/gim, '<br>');
}

async function sendMessage(text) {
    const history = document.getElementById('chat-history');
    const inputField = document.getElementById('chat-input');
    if (!text || !history) return;

    appendMessage('user', `<b>You:</b> ${text}`);
    if(inputField) inputField.value = ''; 

    const loadingId = 'loading-' + Date.now();
    const loadingDiv = document.createElement('div');
    loadingDiv.id = loadingId;
    loadingDiv.className = 'mr-auto max-w-[85%] bg-deloitte-canvas text-deloitte-coolGray p-3 rounded-lg rounded-tl-none animate-pulse border border-deloitte-lightGray shadow-sm';
    loadingDiv.innerHTML = `<i>Thinking...</i>`;
    history.appendChild(loadingDiv);
    history.scrollTop = history.scrollHeight;

    // Seamlessly attach context to the question payload
    const contextString = assistantData.context.recordHtml ? `\n\n[System Note: The user is currently viewing the following record context: ${assistantData.context.recordHtml}]` : '';
    const payloadText = text + contextString;

    try {
        const response = await fetch('https://agentbuilder3.ingenw-innovation-nonprod.deloitte.com/api/v1/prediction/a70f8f8e-a621-47a6-a7c9-20dd347bf0e5', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ question: payloadText }) 
        });

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        const loadingEl = document.getElementById(loadingId);
        if(loadingEl) loadingEl.remove();

        const replyText = data.text || data.answer || JSON.stringify(data); 
        const formattedReply = parseMarkdown(replyText);

        appendMessage('bot', formattedReply);

    } catch (error) {
        const loadingEl = document.getElementById(loadingId);
        if(loadingEl) loadingEl.remove();
        appendMessage('bot', `<span class="text-[#D32F2F] text-xs"><b>System Error:</b> Could not reach AI (${error.message}).</span>`);
    }
}

// Wire up Enter Key for Chat
setTimeout(() => {
    const inputField = document.getElementById('chat-input');
    if (inputField) {
        inputField.addEventListener("keypress", function(event) {
          if (event.key === "Enter") {
            event.preventDefault();
            sendMessage(inputField.value);
            const suggestionsBox = document.getElementById('chat-suggestions');
            if (suggestionsBox) suggestionsBox.style.display = "none";
          }
        });
    }
}, 200);

// --- 3. Appsmith Integration ---
if (typeof appsmith !== 'undefined') {
    appsmith.onReady(() => {
        initAssistant();
    });

    appsmith.onModelChange((model) => {
        // Allow passing in new queue data
        if (model && Array.isArray(model.queueData) && model.queueData.length > 0) {
            queueData = model.queueData;
            renderQueue();
        }

        if (model.activeAuditId) {
            window.selectQueueItem(model.activeAuditId, model.activeAuditData?.vendor || "Unknown Vendor", model.activeAuditData?.score || 0);
        }
    });
} else {
    initAssistant();
}

