      const rating = (v.risk_rating || '').toLowerCase();
      let score;
      if (v.blacklist_status) score = 90 + (i % 10);
      else if (rating === 'high') score = 70 + (i % 20);
      else if (rating === 'medium') score = 35 + (i % 25);
      else score = 5 + (i % 20);

      if (v.official_gstin) validGst++; else suspendedGst++;
      if (v.blacklist_status) blacklistedCount++;
      if (rating === 'high' || v.blacklist_status) highRiskCount++;
      totalScore += score;

      const flags = [];
      if (v.blacklist_status) flags.push('Blacklisted');
      if (!v.official_gstin) flags.push('GSTIN Mismatch');
      if (rating === 'high') flags.push('High Risk');

      return {
        key: v.vendor_id || i,
        name: v.vendor_name || v.vendor_id,
        gstOk: !!v.official_gstin,
        score: score,
        flags: flags,
        isDanger: v.blacklist_status || rating === 'high',
        vendorId: v.vendor_id,
        rating: rating
      };
    }).sort(function (a, b) { return b.score - a.score; });

    const avgScore = vendors.length ? Math.round(totalScore / vendors.length) : 0;
    const clusters = Math.max(1, Math.floor(blacklistedCount / 2));

    const filteredData = tableData.filter(function (r) {
      if (search && !String(r.name).toLowerCase().includes(search.toLowerCase())) return false;
      if (filter === 'high' && r.score <= 75) return false;
      if (filter === 'medium' && (r.score > 75 || r.score <= 45)) return false;
      if (filter === 'low' && r.score > 45) return false;
      return true;
    });

    const highCt = tableData.filter(function (r) { return r.score > 75; }).length;
    const medCt = tableData.filter(function (r) { return r.score > 45 && r.score <= 75; }).length;
    const lowCt = tableData.filter(function (r) { return r.score <= 45; }).length;
    const totalCt = tableData.length || 1;

    const columns = [
      {
        title: 'Vendor', dataIndex: 'name', key: 'name',
        render: function (text, record) {
          const initial = text && text.charAt ? text.charAt(0).toUpperCase() : 'V';
          const cls = record.score > 75 ? 'red' : record.score > 45 ? 'orange' : 'green';
          return (
            <div className="vendor-cell">
              <div className={`avatar avatar-${cls}`}>{initial}</div>
              <div>
                <div className="vendor-name">{text}</div>
                <div className="vendor-id">ID: {record.vendorId || '—'}</div>
              </div>
            </div>
          );
        }
      },
      {
        title: 'GSTIN', dataIndex: 'gstOk', key: 'gst',
        render: function (ok) {
          return <span className={`status-tag ${ok ? 'tag-green' : 'tag-red'}`}>{ok ? '● Active' : '● Suspended'}</span>;
        }
      },
      {
        title: 'Shell Risk Score', dataIndex: 'score', key: 'score',
        render: function (score) { return <ScoreBar score={score} />; }
      },
      {
        title: 'Collusion Flags', dataIndex: 'flags', key: 'flags',
        render: function (flags) {
          if (!flags || flags.length === 0) return <span className="flag-none">— None —</span>;
          return (
            <div className="flag-chips">
              {flags.map(function (f) { return <span key={f} className="flag-chip">{f}</span>; })}
            </div>
          );
        }
      },
      {
        title: '', dataIndex: 'action', key: 'action', align: 'right', width: 130,
        render: function (_, record) {
          return (
            <button
              className="view-btn"
              onClick={function () { appsmith.triggerEvent('onProfileClick', { vendorId: record.vendorId }); }}
            >View Profile →</button>
          );
        }
      }
    ];

    return (
      <div className="vi-page">
        <div className="vi-header">
          <div>
            <div className="breadcrumb">Risk &amp; Compliance <span>›</span> Vendor Intelligence</div>
            <h2><GreenDot /> Vendor Intelligence</h2>
            <p className="subtitle">Real-time analysis of vendor risk, collusion patterns, and shell company indicators</p>
          </div>
          <div className="header-actions">
            <button className="btn btn-secondary">⬇ Export Report</button>
            <button className="btn btn-primary">↻ Refresh External Data</button>
          </div>
        </div>

        <div className="kpi-strip">
          <KpiCard label="Total Vendors" value={vendors.length} trend="Across all units" accent="neutral" icon="🏢" />
          <KpiCard label="High Risk" value={highRiskCount} trend={Math.round(highRiskCount / vendors.length * 100) + '% of portfolio'} accent="danger" icon="⚠" />
          <KpiCard label="Blacklisted" value={blacklistedCount} trend="Immediate review" accent="warning" icon="🚫" />
          <KpiCard label="Avg Risk Score" value={avgScore} trend={avgScore > 50 ? 'Elevated' : 'Within tolerance'} accent="info" icon="📊" />
        </div>

        <div className="top-row">
          <Card title="Vendor Network Graph" extra={<span className="card-extra">Collusion Detection</span>} bodyStyle={{ padding: 0 }}>
            <NetworkGraph />
          </Card>
          <Card title="External Risk Metrics" extra={<span className="card-extra">Live</span>}>
            <RiskMetrics validGst={validGst} suspendedGst={suspendedGst} clusters={clusters} total={vendors.length} />
          </Card>
        </div>

        <Card title="Risk Severity Distribution" extra={<span className="card-extra">{tableData.length} vendors</span>}>
          <div className="severity-bar">
            <div className="seg seg-red" style={{ width: ((highCt / totalCt) * 100) + '%' }} />
            <div className="seg seg-orange" style={{ width: ((medCt / totalCt) * 100) + '%' }} />
            <div className="seg seg-green" style={{ width: ((lowCt / totalCt) * 100) + '%' }} />
          </div>
          <div className="severity-legend">
            <span><i className="dot dot-red" />High Risk <b>{highCt}</b></span>
            <span><i className="dot dot-orange" />Medium <b>{medCt}</b></span>
            <span><i className="dot dot-green" />Low Risk <b>{lowCt}</b></span>
          </div>
        </Card>

        <Card
          title="Vendor Master List"
          extra={
            <div className="table-toolbar">
              <div className="search-input-wrap">
                <span className="search-icon">🔍</span>
                <input
                  type="text"
                  className="search-input"
                  placeholder="Search vendor..."
                  value={search}
                  onChange={this.handleSearch}
                />
                {search ? <span className="clear-icon" onClick={this.clearSearch}>✕</span> : null}
              </div>
              <select className="filter-select" value={filter} onChange={this.handleFilter}>
                <option value="all">All Severities</option>
                <option value="high">High Only</option>
                <option value="medium">Medium Only</option>
                <option value="low">Low Only</option>
              </select>
            </div>
          }
        >
          <CustomTable columns={columns} data={filteredData} />
        </Card>
      </div>
    );
  }
}

appsmith.onReady(function () {
  reactDom.render(<App />, document.getElementById("root"));
});

