srcDoc.css:
:root {
  --deloitte-green: #86BC25;
  --deloitte-green-dark: #6B9B1E;
  --deloitte-green-light: #E8F5D4;
  --deloitte-blue: #00A3E0;
  --deloitte-teal: #004F59;
  --deloitte-teal-dark: #003540;
  --black: #0F0B0B;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --border: #E8E8E6;
  --canvas: #FBFBFB;
  --white: #FFFFFF;
  --danger: #D32F2F;
  --warning: #ED6C02;
  --success: #2E7D32;
  --shadow-sm: 0 1px 2px rgba(15,11,11,0.04);
  --shadow-md: 0 2px 8px rgba(15,11,11,0.06);
}

* {
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--canvas);
  margin: 0;
  color: var(--black);
}

.vi-page {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 28px 32px;
  max-width: 1600px;
  margin: 0 auto;
}

/* Green Dot signature */
.green-dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  background: var(--deloitte-green);
  border-radius: 50%;
  margin-right: 10px;
  vertical-align: middle;
  box-shadow: 0 0 0 4px rgba(134, 188, 37, 0.15);
}

/* Header */
.vi-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.breadcrumb {
  font-size: 12px;
  color: var(--cool-gray);
  margin-bottom: 6px;
  font-weight: 500;
}

.breadcrumb span {
  margin: 0 6px;
  color: var(--light-gray);
}

.vi-header h2 {
  font-size: 26px;
  font-weight: 700;
  color: var(--black);
  margin: 0 0 4px 0;
  letter-spacing: -0.3px;
}

.subtitle {
  font-size: 13px;
  color: var(--cool-gray);
  margin: 0;
  max-width: 520px;
}

.header-actions {
  display: flex;
  gap: 10px;
}

/* Buttons */
.btn {
  height: 38px;
  padding: 0 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid var(--border);
  transition: all 0.15s ease;
  font-family: inherit;
}

.btn-secondary {
  background: var(--white);
  color: var(--black);
}

.btn-secondary:hover {
  background: var(--canvas);
  border-color: var(--cool-gray);
}

.btn-primary {
  background: var(--deloitte-green);
  color: var(--white);
  border-color: var(--deloitte-green);
  box-shadow: 0 2px 6px rgba(134, 188, 37, 0.3);
}

.btn-primary:hover {
  background: var(--deloitte-green-dark);
  border-color: var(--deloitte-green-dark);
}

/* KPI Strip */
.kpi-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.kpi-card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 18px 20px;
  display: flex;
  align-items: center;
  gap: 14px;
  box-shadow: var(--shadow-sm);
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.kpi-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
}

.kpi-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
}

.kpi-neutral::before {
  background: var(--deloitte-green);
}

.kpi-danger::before {
  background: var(--danger);
}

.kpi-warning::before {
  background: var(--warning);
}

.kpi-info::before {
  background: var(--deloitte-blue);
}

.kpi-icon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--canvas);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.kpi-neutral .kpi-icon {
  background: var(--deloitte-green-light);
}

.kpi-danger .kpi-icon {
  background: #FFEBEE;
}

.kpi-warning .kpi-icon {
  background: #FFF3E0;
}

.kpi-info .kpi-icon {
  background: #E1F5FE;
}

.kpi-label {
  font-size: 11px;
  color: var(--cool-gray);
  margin: 0 0 2px 0;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  font-weight: 600;
}

.kpi-value {
  font-size: 26px;
  font-weight: 700;
  color: var(--black);
  margin: 0;
  line-height: 1.1;
  letter-spacing: -0.5px;
}

.kpi-trend {
  font-size: 11px;
  color: var(--cool-gray);
  margin: 4px 0 0 0;
}

/* Card */
.card {
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 10px;
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.card-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 18px;
  border-bottom: 1px solid var(--border);
  min-height: 48px;
}

.card-title {
  font-size: 13px;
  font-weight: 700;
  color: var(--black);
  letter-spacing: 0.2px;
}

.card-body {
  padding: 18px;
}

.card-extra {
  font-size: 11px;
  color: var(--cool-gray);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  background: var(--canvas);
  padding: 3px 10px;
  border-radius: 99px;
  border: 1px solid var(--border);
}

/* Top row */
.top-row {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 16px;
}

/* Network graph */
.network-canvas {
  background: linear-gradient(135deg, var(--deloitte-teal) 0%, var(--deloitte-teal-dark) 100%);
  border-radius: 0 0 10px 10px;
  position: relative;
  overflow: hidden;
  height: 280px;
  width: 100%;
}

.network-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.node-text {
  font-size: 11px;
  font-weight: 700;
  fill: var(--black);
}

.node-text-w {
  font-size: 9px;
  font-weight: 700;
  fill: #fff;
}

@keyframes dash {
  to {
    stroke-dashoffset: -18;
  }
}
.edge-anim {
  animation: dash 1.2s linear infinite;
}

@keyframes pulse {
  0% {
    r: 22;
    opacity: 0.9;
  }
  100% {
    r: 38;
    opacity: 0;
  }
}
.pulse-ring {
  animation: pulse 1.8s ease-out infinite;
  transform-origin: center;
}

.alert-overlay {
  position: absolute;
  bottom: 14px;
  left: 14px;
  background: rgba(15, 11, 11, 0.85);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: #fff;
  font-size: 11px;
  padding: 12px 14px;
  border-radius: 8px;
  max-width: 300px;
  line-height: 1.5;
  border-left: 3px solid var(--danger);
}

.alert-overlay p {
  margin: 4px 0 0 0;
}

.alert-tag {
  color: #FF6B6B;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.8px;
}

.graph-legend {
  position: absolute;
  top: 14px;
  right: 14px;
  display: flex;
  gap: 14px;
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  padding: 8px 12px;
  border-radius: 6px;
}

.graph-legend span {
  color: #fff;
  font-size: 10px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
}

.dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot-green {
  background: var(--deloitte-green);
}

.dot-black {
  background: var(--black);
  border: 1px solid #fff;
}

.dot-red {
  background: var(--danger);
}

.dot-orange {
  background: var(--warning);
}

/* Risk Metrics */
.risk-metrics {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.metric-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.metric-row .label {
  font-size: 13px;
  font-weight: 600;
  color: var(--black);
  margin: 0;
}

.metric-row .sublabel {
  font-size: 11px;
  color: var(--cool-gray);
  margin: 2px 0 0 0;
}

.metric-row .val {
  font-size: 22px;
  font-weight: 700;
}

.val-green {
  color: var(--success);
}

.val-red {
  color: var(--danger);
}

.mini-bar {
  height: 4px;
  background: var(--canvas);
  border-radius: 99px;
  margin-top: 10px;
  overflow: hidden;
}

.mini-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--deloitte-green), var(--deloitte-green-dark));
  border-radius: 99px;
  transition: width 0.6s ease;
}

.custom-divider {
  height: 1px;
  background: var(--border);
  margin: 14px 0;
}

.highlight-box {
  background: linear-gradient(135deg, #FFF3E0 0%, #FFE0B2 100%);
  padding: 14px;
  border-radius: 8px;
  margin-top: auto;
  display: flex;
  align-items: center;
  gap: 12px;
}

.hl-icon {
  font-size: 24px;
  width: 40px;
  height: 40px;
  background: rgba(237, 108, 2, 0.15);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hl-label {
  font-size: 11px;
  color: #BF360C;
  font-weight: 600;
  margin: 0 0 2px 0;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.hl-value {
  font-size: 22px;
  color: var(--warning);
  font-weight: 700;
  margin: 0;
  line-height: 1;
}

.hl-unit {
  font-size: 12px;
  color: var(--cool-gray);
  font-weight: 500;
}

/* Severity bar */
.severity-bar {
  display: flex;
  height: 14px;
  border-radius: 99px;
  overflow: hidden;
  background: var(--canvas);
  margin-bottom: 14px;
}

.seg {
  height: 100%;
  transition: width 0.6s ease;
}

.seg-red {
  background: var(--danger);
}

.seg-orange {
  background: var(--warning);
}

.seg-green {
  background: var(--deloitte-green);
}

.severity-legend {
  display: flex;
  gap: 24px;
  font-size: 12px;
  color: var(--cool-gray);
}

.severity-legend span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.severity-legend b {
  color: var(--black);
  margin-left: 4px;
  font-weight: 700;
}

/* Toolbar */
.table-toolbar {
  display: flex;
  gap: 10px;
  align-items: center;
}

.search-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.search-icon {
  position: absolute;
  left: 10px;
  font-size: 12px;
  pointer-events: none;
  opacity: 0.5;
}

.search-input {
  height: 32px;
  width: 200px;
  padding: 0 28px 0 30px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 12px;
  background: var(--white);
  font-family: inherit;
  outline: none;
  transition: border-color 0.15s ease;
}

.search-input:focus {
  border-color: var(--deloitte-green);
}

.clear-icon {
  position: absolute;
  right: 8px;
  font-size: 12px;
  cursor: pointer;
  color: var(--cool-gray);
  padding: 2px 4px;
}

.clear-icon:hover {
  color: var(--black);
}

.filter-select {
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 12px;
  background: var(--white);
  font-family: inherit;
  cursor: pointer;
  outline: none;
}

.filter-select:focus {
  border-color: var(--deloitte-green);
}

/* Custom Table */
.custom-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.custom-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.custom-table thead th {
  background: var(--canvas);
  color: var(--cool-gray);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  font-weight: 700;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}

.custom-table tbody td {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
  vertical-align: middle;
}

.custom-table tbody tr:hover td {
  background: var(--canvas);
}

.custom-table tbody tr.row-danger td {
  background: #FFF5F5;
}

.custom-table tbody tr.row-danger:hover td {
  background: #FFEBEE;
}

.empty-row {
  text-align: center !important;
  padding: 40px !important;
  color: var(--cool-gray);
  font-style: italic;
}

/* Vendor cell */
.vendor-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 13px;
  color: #fff;
  flex-shrink: 0;
}

.avatar-red {
  background: linear-gradient(135deg, #EF5350, var(--danger));
}

.avatar-orange {
  background: linear-gradient(135deg, #FFB74D, var(--warning));
}

.avatar-green {
  background: linear-gradient(135deg, #AED581, var(--deloitte-green));
}

.vendor-name {
  font-weight: 600;
  color: var(--black);
  font-size: 13px;
}

.vendor-id {
  font-size: 11px;
  color: var(--cool-gray);
  font-family: "SF Mono", Monaco, monospace;
}

/* Status tag */
.status-tag {
  display: inline-block;
  font-weight: 600;
  font-size: 11px;
  border-radius: 4px;
  padding: 3px 10px;
  border: 1px solid;
}

.tag-green {
  background: var(--deloitte-green-light);
  color: var(--success);
  border-color: #C8E6C9;
}

.tag-red {
  background: #FFEBEE;
  color: var(--danger);
  border-color: #FFCDD2;
}

/* Score bar */
.score-bar-wrap {
  display: flex;
  align-items: center;
  gap: 10px;
}

.score-track {
  width: 80px;
  height: 6px;
  background: var(--canvas);
  border-radius: 99px;
  overflow: hidden;
  border: 1px solid var(--border);
}

.score-fill {
  height: 100%;
  border-radius: 99px;
  transition: width 0.5s ease;
}

.sf-red {
  background: linear-gradient(90deg, #EF5350, var(--danger));
}

.sf-orange {
  background: linear-gradient(90deg, #FFB74D, var(--warning));
}

.sf-green {
  background: linear-gradient(90deg, #AED581, var(--deloitte-green));
}

.score-num {
  font-weight: 700;
  color: var(--black);
  font-size: 13px;
  min-width: 24px;
}

.score-pill {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 99px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.sf-pill-sf-red {
  background: #FFEBEE;
  color: var(--danger);
}

.sf-pill-sf-orange {
  background: #FFF3E0;
  color: var(--warning);
}

.sf-pill-sf-green {
  background: var(--deloitte-green-light);
  color: var(--success);
}

/* Flag chips */
.flag-chips {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.flag-chip {
  background: #FFEBEE;
  color: var(--danger);
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.flag-none {
  color: var(--light-gray);
  font-size: 12px;
}

/* View profile button */
.view-btn {
  background: none;
  border: none;
  color: var(--deloitte-blue);
  font-weight: 600;
  font-size: 12px;
  cursor: pointer;
  padding: 4px 8px;
  font-family: inherit;
  transition: color 0.15s ease;
}

.view-btn:hover {
  color: var(--deloitte-teal);
}

/* Empty state */
.empty-state {
  padding: 80px 40px;
  text-align: center;
  color: var(--cool-gray);
}

.empty-icon {
  font-size: 48px;
  margin-bottom: 12px;
  opacity: 0.5;
}

.empty-state h3 {
  font-size: 16px;
  color: var(--black);
  margin: 0 0 6px 0;
  font-weight: 600;
}

.empty-state p {
  margin: 0;
  font-size: 13px;
}

