        {props.extra ? <span className="card-extra-wrap">{props.extra}</span> : null}
      </div>
      <div className="card-body" style={props.bodyStyle || {}}>
        {props.children}
      </div>
    </div>
  );
}

// ─── Custom Table (replaces antd Table) ───
function CustomTable(props) {
  const columns = props.columns;
  const data = props.data;
  return (
    <div className="custom-table-wrap">
      <table className="custom-table">
        <thead>
          <tr>
            {columns.map(function (c) {
              return <th key={c.key} style={{ textAlign: c.align || 'left', width: c.width }}>{c.title}</th>;
            })}
          </tr>
        </thead>
        <tbody>
          {data.length === 0 ? (
            <tr><td colSpan={columns.length} className="empty-row">No vendors match your filters</td></tr>
          ) : data.map(function (row) {
            return (
              <tr key={row.key} className={row.isDanger ? 'row-danger' : ''}>
                {columns.map(function (c) {
                  const value = row[c.dataIndex];
                  return (
                    <td key={c.key} style={{ textAlign: c.align || 'left' }}>
                      {c.render ? c.render(value, row) : value}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

