            <button className="btn btn-primary">↻ Refresh External Data</button>
          </div>
        </div>

        <div className="kpi-strip">
          <KpiCard label="Total Vendors" value={vendors.length} trend="Across all units" accent="neutral" icon="🏢" />
          <KpiCard label="High Risk" value={highRiskCount} trend={Math.round(highRiskCount / vendors.length * 100) + '% of portfolio'} accent="danger" icon="⚠" />
          <KpiCard label="Blacklisted" value={blacklistedCount} trend="Immediate review" accent="warning" icon="🚫" />
          <KpiCard label="Avg Risk Score" value={avgScore} trend={avgScore > 50 ? 'Elevated' : 'Within tolerance'} accent="info" icon="📊" />
        </div>

        <div className="top-row">
          <Card title="Vendor Network Graph" extra={<span className="card-extra">Collusion Detection</span>} bodyStyle={{ padding: 0 }}>
            <NetworkGraph />
          </Card>
          <Card title="External Risk Metrics" extra={<span className="card-extra">Live</span>}>
            <RiskMetrics validGst={validGst} suspendedGst={suspendedGst} clusters={clusters} total={vendors.length} />
          </Card>
        </div>

        <Card title="Risk Severity Distribution" extra={<span className="card-extra">{tableData.length} vendors</span>}>
          <div className="severity-bar">
