            <div className="seg seg-orange" style={{ width: ((medCt / totalCt) * 100) + '%' }} />
            <div className="seg seg-green" style={{ width: ((lowCt / totalCt) * 100) + '%' }} />
          </div>
          <div className="severity-legend">
            <span><i className="dot dot-red" />High Risk <b>{highCt}</b></span>
            <span><i className="dot dot-orange" />Medium <b>{medCt}</b></span>
            <span><i className="dot dot-green" />Low Risk <b>{lowCt}</b></span>
