// This gives them the "duplicate cluster detection" they asked for
function DuplicateClusters() {
  const clusters = [
    { id: '#801', count: 4, amount: '$48,000', vendor: 'TechCorp Logistics' },
    { id: '#802', count: 3, amount: '$36,000', vendor: 'Prime Manufacturing' },
    { id: '#803', count: 2, amount: '$24,000', vendor: 'Apex Solutions' }
  ];

