          <div>
            <div style={{ fontWeight: 600, color: 'var(--black)', fontSize: 14 }}>
              Cluster {c.id}
            </div>
            <div style={{ fontSize: 12, color: 'var(--cool-gray)', marginTop: 4 }}>
              {c.vendor}
            </div>
          </div>
          <div style={{ textAlign: 'right' }}>
            <div style={{ fontWeight: 700, color: 'var(--danger)', fontSize: 15 }}>
              {c.amount}
            </div>
            <div style={{ marginTop: 6 }}>
              <span className="cluster-badge">{c.count} Duplicates Found</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

// ─── Live Ticker Component ───
