function LiveTicker() {
  return (
    <div className="ticker-wrap">
      <div className="pulse-dot"></div>
      <div style={{ fontWeight: 700, letterSpacing: '0.5px' }}>LIVE FEED:</div>
      <marquee scrollamount="5" style={{ fontSize: 14, fontWeight: 500 }}>
        [URGENT] Invoice INV40008 flagged for Critical Risk (Dave Suspect) &nbsp;&nbsp;&nbsp; | &nbsp;&nbsp;&nbsp; 
        Agent 2B detected GSTIN formatting error for Global Supplies Inc &nbsp;&nbsp;&nbsp; | &nbsp;&nbsp;&nbsp; 
        Automated Escalation sent to CAO for Review Queue #42
      </marquee>
    </div>
  );
}

