@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --deloitte-green: #86BC25;
  --cool-black: #0F0B0B;
  --pure-white: #FFFFFF;
  --cool-gray: #75787B;
  --light-gray: #D0D0CE;
  --deloitte-blue: #00A3E0;
  --dark-teal: #004F59;
  --bg-color: #FBFBFB;
  --danger-red: #D22B2B;
}

.app {
  font-family: 'Inter', sans-serif;
  color: var(--cool-black);
  background-color: var(--bg-color);
  padding: 24px;
  height: 100vh;
  box-sizing: border-box;
  overflow-y: auto;
  position: relative;
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes slideDown {
  from { opacity: 0; transform: translate(-50%, -20px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

.fade-in {
  animation: fadeIn 0.5s ease-out forwards;
}

/* Toast Notifications */
.toast {
  position: fixed;
  top: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--pure-white);
  border: 1px solid var(--light-gray);
  box-shadow: 0 8px 24px rgba(0,0,0,0.12);
  padding: 12px 20px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 12px;
  z-index: 1000;
  animation: slideDown 0.3s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  font-weight: 500;
  font-size: 14px;
}

.toast.success .toast-icon { color: var(--deloitte-green); }
.toast.info .toast-icon { color: var(--deloitte-blue); }

.toast-close {
  background: transparent;
  border: none;
  color: var(--cool-gray);
  cursor: pointer;
  display: flex;
  align-items: center;
  margin-left: 12px;
  padding: 4px;
  border-radius: 4px;
}

.toast-close:hover {
  background: var(--bg-color);
  color: var(--cool-black);
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 32px;
}

.header h2 {
  font-size: 28px;
  font-weight: 700;
  margin: 0;
  color: var(--cool-black);
  letter-spacing: -0.5px;
}

.header p {
  color: var(--cool-gray);
  margin-top: 4px;
  font-size: 15px;
}

.generate-btn {
  background: linear-gradient(135deg, var(--deloitte-green), #75a620);
  color: var(--pure-white);
  border: none;
  padding: 12px 24px;
  border-radius: 8px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 4px 15px rgba(134, 188, 37, 0.3);
  display: flex;
  align-items: center;
  gap: 8px;
}

.generate-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(134, 188, 37, 0.4);
}

.generate-btn:active {
  transform: translateY(0);
}

/* KPI Section */
.kpi-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin-bottom: 32px;
}

.kpi-card {
  background: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
  transition: all 0.3s ease;
  box-shadow: 0 2px 8px rgba(0,0,0,0.02);
  animation: fadeIn 0.5s ease-out backwards;
}

.kpi-card:hover {
  border-color: var(--deloitte-green);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0,0,0,0.06);
}

.kpi-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--deloitte-green);
  background: rgba(134, 188, 37, 0.1);
}

.kpi-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--cool-black);
  margin-bottom: 2px;
}

.kpi-label {
  font-size: 13px;
  color: var(--cool-gray);
  font-weight: 500;
}

/* Reports Grid */
.reports-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
}

.report-card {
  background: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.02);
  position: relative;
  overflow: hidden;
  animation: fadeIn 0.6s ease-out backwards;
}

.report-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 4px;
  background: var(--deloitte-green);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}

.report-card:hover {
  border-color: transparent;
  box-shadow: 0 12px 32px rgba(0,0,0,0.08);
  transform: translateY(-4px);
}

.report-card:hover::before {
  transform: scaleX(1);
}

.report-card h3 {
  font-size: 18px;
  font-weight: 700;
  margin: 0 0 8px 0;
  color: var(--cool-black);
  transition: color 0.2s;
}

.report-card:hover h3 {
  color: var(--deloitte-green);
}

.report-card .date {
  font-size: 12px;
  font-weight: 700;
  color: var(--deloitte-green);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin: 0 0 16px 0;
  display: inline-block;
  background: rgba(134, 188, 37, 0.1);
  padding: 4px 8px;
  border-radius: 4px;
}

.report-card .desc {
  font-size: 14px;
  color: var(--cool-gray);
  line-height: 1.6;
  margin: 0 0 24px 0;
  flex-grow: 1;
}

.card-actions {
  display: flex;
  gap: 12px;
  border-top: 1px solid var(--light-gray);
  padding-top: 16px;
}

.card-actions button {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: transparent;
  border: 1px solid var(--light-gray);
  padding: 10px;
  border-radius: 8px;
  color: var(--cool-gray);
  font-weight: 600;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.card-actions button:hover {
  background: var(--pure-white);
  border-color: var(--deloitte-green);
  color: var(--deloitte-green);
  box-shadow: 0 2px 8px rgba(134, 188, 37, 0.15);
}

/* History Table Section */
.history-section {
  margin-top: 40px;
  background: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.02);
}

.history-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
  gap: 16px;
}

.history-header h3 {
  font-size: 18px;
  font-weight: 700;
  color: var(--cool-black);
  margin: 0;
}

.history-controls {
  display: flex;
  gap: 12px;
}

.search-box, .filter-box {
  display: flex;
  align-items: center;
  background: var(--pure-white);
  border: 1px solid var(--light-gray);
  border-radius: 8px;
  padding: 8px 12px;
  gap: 8px;
  color: var(--cool-gray);
  transition: border-color 0.2s;
}

.search-box:focus-within, .filter-box:focus-within {
  border-color: var(--deloitte-green);
}

.search-box input {
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 13px;
  width: 180px;
  color: var(--cool-black);
}

.filter-box select {
  border: none;
  outline: none;
  font-family: inherit;
  font-size: 13px;
  color: var(--cool-black);
  background: transparent;
  cursor: pointer;
}

.table-wrapper {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

th {
  font-size: 12px;
  color: var(--cool-gray);
  font-weight: 600;
  text-transform: uppercase;
  padding: 12px 16px;
  border-bottom: 2px solid var(--light-gray);
}

td {
  padding: 16px;
  font-size: 14px;
  color: var(--cool-black);
  border-bottom: 1px solid var(--light-gray);
}

tr:hover td {
  background-color: var(--bg-color);
}

.mono {
  font-family: monospace;
  font-weight: 500;
  color: var(--cool-gray);
}

.fw-600 {
  font-weight: 600;
}

.status-badge {
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}

.status-completed {
  background: rgba(134, 188, 37, 0.1);
  color: var(--deloitte-green);
}

.status-pending {
  background: rgba(0, 163, 224, 0.1);
  color: var(--deloitte-blue);
}

.status-failed {
  background: rgba(210, 43, 43, 0.1);
  color: var(--danger-red);
}

.btn-text {
  background: none;
  border: none;
  color: var(--deloitte-green);
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 6px;
  transition: all 0.2s;
}

.btn-text:hover:not(:disabled) {
  background: rgba(134, 188, 37, 0.1);
}

.btn-text:disabled {
  color: var(--light-gray);
  cursor: not-allowed;
}

/* Empty State */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 20px;
  text-align: center;
}

.empty-icon {
  color: var(--light-gray);
  margin-bottom: 16px;
}

.empty-state h4 {
  margin: 0 0 8px 0;
  font-size: 16px;
  color: var(--cool-black);
}

.empty-state p {
  margin: 0 0 24px 0;
  color: var(--cool-gray);
  font-size: 14px;
}

.btn-outline {
  background: transparent;
  border: 1px solid var(--light-gray);
  padding: 8px 16px;
  border-radius: 6px;
  color: var(--cool-black);
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-outline:hover {
  border-color: var(--deloitte-green);
  color: var(--deloitte-green);
}

/* Responsive Media Queries */
@media (max-width: 1024px) {
  .kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }
  .history-header {
    flex-direction: column;
    align-items: flex-start;
  }
  .history-controls {
    width: 100%;
    flex-direction: column;
  }
  .search-box, .filter-box {
    width: 100%;
  }
  .search-box input {
    width: 100%;
  }
  .toast {
    width: 90%;
    top: 10px;
  }
}

@media (max-width: 480px) {
  .app {
    padding: 16px;
  }
  .kpi-row {
    grid-template-columns: 1fr;
  }
  .header h2 {
    font-size: 24px;
  }
  .generate-btn {
    width: 100%;
    justify-content: center;
  }
}

